import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Arredondar os cantos de uma foto leva só alguns minutos. Você envia a imagem, arrasta um controle para definir a curva e baixa o resultado suavizado.</p>\n<p>Este passo a passo cobre o processo inteiro. Você vai ver o controle de raio, o controle por canto, o atalho de círculo completo, as opções de preenchimento e os formatos de exportação que mantêm os cantos transparentes.</p>\n<p>No final, você vai conseguir fazer um avatar arredondado, uma imagem de cartão ou um banner em forma de pílula em qualquer dispositivo. Guarde a foto original até conferir o resultado.</p>\n<h2 id=\"before-you-start\">Antes de começar: escolha a forma</h2>\n<p>Decida que forma você precisa antes de abrir a ferramenta. Um círculo combina com avatar, um arredondamento leve combina com cartão e uma pílula combina com banner ou selo.</p>\n<p>Confira o destino também. Um espaço de perfil pode exigir um círculo, enquanto um cartão de blog pode precisar só dos dois cantos de cima arredondados.</p>\n<p>Use a foto original, não uma cópia comprimida. Arredondar a partir de uma original nítida mantém as bordas curvas suaves, enquanto arredondar uma cópia macia deixa as curvas ásperas.</p>\n<p>Abra a ferramenta <a href=\"/pt/arredondar-cantos-da-imagem/\">Arredondar cantos da imagem</a> no seu navegador. Tudo roda localmente, então sua foto nunca é enviada para um servidor.</p>\n<h2 id=\"step-by-step\">Arredonde cantos de imagem em cinco passos</h2>\n<p>O processo é o mesmo para um arredondamento leve e para um círculo completo. Envie, defina o raio, escolha o preenchimento, confira a prévia e baixe.</p>\n<p>Leve o raio com calma. Uma pequena mudança no valor pode fazer uma grande diferença na sensação da forma, então observe a prévia enquanto arrasta.</p>\n<ol>\n<li>Envie sua imagem arrastando-a para a área de envio, escolhendo-a no seu dispositivo ou colando uma captura de tela com Ctrl+V.</li>\n<li>Arraste o controle Raio de todos os cantos para definir a curva, observando o valor em pixels ao vivo enquanto ajusta.</li>\n<li>Ative o modo por canto para definir raios diferentes, ou use o atalho Círculo completo / Pílula para uma forma redonda ou de pílula.</li>\n<li>Escolha Transparente em Preenchimento dos cantos externos para cantos vazados, ou Cor sólida para um fundo preenchido.</li>\n<li>Escolha o formato de exportação, PNG ou WebP para manter a transparência, e clique em Baixar para salvar o resultado.</li>\n</ol>\n<p>Abra o arquivo baixado uma vez antes de usá-lo. Confirme que os cantos ficaram suaves e que nada importante foi cortado.</p>\n<h2 id=\"setting-radius\">Como definir o raio do canto</h2>\n<p>O controle de raio define o quanto os cantos ficam redondos. Um valor pequeno dá uma suavização leve, enquanto um valor grande transforma os cantos em curvas profundas.</p>\n<p>Um raio de 10 a 20 pixels combina com cartões, miniaturas e capturas de tela. O arredondamento é sutil, e a imagem continua parecendo um retângulo de bordas suaves.</p>\n<p>Um raio de 50 a 100 pixels dá um visual claramente arredondado. Combina com avatares, posts de redes sociais e gráficos de aplicativo, onde a forma faz parte do design.</p>\n<p>Observe o valor em pixels ao vivo ao lado do controle. Ele mostra o valor exato do raio, para você reproduzir o mesmo arredondamento em outra imagem depois.</p>\n<h2 id=\"per-corner-mode\">Como usar o modo por canto</h2>\n<p>O modo por canto permite definir um raio diferente para cada canto. Ao ativá-lo, aparecem quatro controles separados, um para cada canto da imagem.</p>\n<p>Um cartão de blog é o caso clássico. Arredonde os dois cantos de cima e deixe os dois de baixo quadrados, para a foto ficar direitinho no topo do cartão.</p>\n<p>Ao desligar o modo por canto, volta um único raio para todos os cantos. Os valores individuais são guardados enquanto o modo está desligado, então dá para voltar sem perdê-los.</p>\n<p>Use o controle por canto com moderação. Um design com quatro raios diferentes parece acidental, enquanto um ou dois cantos arredondados com o resto quadrado parece intencional.</p>\n<h2 id=\"full-circle-shortcut\">Como usar o atalho Círculo completo / Pílula</h2>\n<p>O atalho Círculo completo define o raio como metade do tamanho da imagem num só clique. Numa foto quadrada, ele cria um círculo perfeito, e num retângulo, cria uma pílula.</p>\n<p>Para um círculo limpo, corte a foto em 1:1 primeiro. Uma fonte quadrada com o atalho dá um avatar redondo e perfeito que cabe em qualquer espaço de perfil.</p>\n<p>Numa foto retangular, o atalho cria uma pílula: um retângulo com as pontas totalmente arredondadas. Pílulas combinam com botões, selos e banners.</p>\n<p>Confira o resultado antes de baixar. Uma pílula pode ficar elegante, mas também pode cortar conteúdo importante nas laterais de uma foto larga.</p>\n<h2 id=\"choosing-fill\">Como escolher preenchimento transparente ou sólido</h2>\n<p>Quando os cantos são cortados, o espaço vazio precisa ser preenchido. Transparente deixa os cantos vazados, enquanto sólido os preenche com uma cor.</p>\n<p>Escolha transparente para gráficos de web, avatares e sobreposições. A imagem se mistura com qualquer fundo, porque os cantos mostram o que está atrás dela.</p>\n<p>Escolha sólido quando o destino não aceita transparência. Um preenchimento branco sólido faz a imagem parecer uma foto arredondada sobre um cartão branco, o que combina com documentos e impressões.</p>\n<p>Se você clicar em transparente com o JPG selecionado, a ferramenta muda o formato automaticamente. O JPG não tem transparência, então ela leva você para PNG ou WebP.</p>\n<h2 id=\"choosing-format\">Como escolher o formato de exportação</h2>\n<p>Escolha PNG para o resultado mais nítido com transparência. Ele não tem perda de qualidade, então as bordas curvas ficam suaves, e funciona em todo lugar, inclusive em navegadores antigos.</p>\n<p>Escolha WebP quando quiser arquivos pequenos com transparência. Ele gera arquivos menores que o PNG com os mesmos cantos vazados, embora alguns sistemas mais antigos o rejeitem.</p>\n<p>Escolha JPG só quando os cantos tiverem um preenchimento sólido. O JPG não tem transparência, então uma exportação transparente em JPG ganha um preenchimento sólido, que pode não combinar com o seu fundo.</p>\n<p>Para gráficos arredondados de web, PNG ou WebP é a escolha certa. Para uma foto arredondada numa página branca, JPG com preenchimento branco funciona bem.</p>\n<h2 id=\"previewing\">Prévia antes de baixar</h2>\n<p>Confira sempre a prévia antes de baixar. Veja se os cantos estão suaves, se o raio parece certo e se nada importante foi cortado.</p>\n<p>Dê zoom num canto e olhe a curva. Um arco suave significa que o arredondamento funcionou bem, enquanto uma borda serrilhada significa que a fonte era pequena ou macia demais.</p>\n<p>Confira o preenchimento sobre o fundo onde a imagem vai ficar. Um canto transparente fica certo em qualquer lugar, enquanto um preenchimento sólido só combina com a cor para a qual foi definido.</p>\n<p>Se o raio parecer errado, ajuste o controle e confira de novo. Uma pequena mudança no valor pode fazer uma grande diferença na sensação da forma.</p>\n<h2 id=\"rounding-for-avatar\">Arredondamento de cantos para um avatar</h2>\n<p>Corte a foto em quadrado primeiro, usando o <a href=\"/pt/cortar-imagens/\">Cortador de imagens</a>. Um corte 1:1 com o rosto centralizado dá o melhor ponto de partida para um avatar redondo.</p>\n<p>Envie a foto quadrada e clique no atalho Círculo completo. O raio salta para metade do tamanho da imagem, e a foto vira um círculo perfeito.</p>\n<p>Mantenha o rosto bem dentro do enquadramento. Os cantos são cortados, então um rosto perto da borda pode perder uma orelha ou parte do cabelo na curva.</p>\n<p>Exporte em PNG ou WebP. A transparência mantém os cantos vazados, então o avatar se mistura com qualquer fundo de perfil, claro ou escuro.</p>\n<h2 id=\"rounding-for-cards\">Arredondamento de cantos para cartões e interface</h2>\n<p>Combine o raio da foto com o raio do cartão. Uma foto com raio de 16 pixels dentro de um cartão com raio de 16 pixels fica perfeita, enquanto raios diferentes parecem descuido.</p>\n<p>Para um cartão de blog, arredonde os dois cantos de cima e deixe os dois de baixo quadrados. Ative o modo por canto, defina os raios de cima e deixe os de baixo em zero.</p>\n<p>Mantenha o raio consistente em todos os cartões de um conjunto. Uma grade de cartões com cantos iguais parece profissional, enquanto raios misturados parecem aleatórios.</p>\n<p>Exporte imagens de cartão em PNG ou WebP quando o cartão estiver sobre um fundo colorido. A transparência mantém os cantos limpos sobre qualquer cor.</p>\n<h2 id=\"rounding-screenshots\">Arredondamento de cantos numa captura de tela</h2>\n<p>Cole uma captura de tela direto com Ctrl+V para pular a etapa de salvar. A imagem aparece na ferramenta na hora, pronta para arredondar.</p>\n<p>Use um raio pequeno, de 10 a 20 pixels, para capturas de tela. Um arredondamento leve faz a captura parecer um cartão de aplicativo moderno sem esconder nenhum conteúdo.</p>\n<p>Exporte capturas arredondadas em PNG. O formato sem perda mantém o texto pequeno nítido, o que importa quando a captura mostra uma configuração ou uma mensagem de erro.</p>\n<p>Mantenha o raio consistente em todas as capturas de um guia. Cantos iguais ajudam o leitor a acompanhar os passos, enquanto raios misturados distraem das instruções.</p>\n<h2 id=\"rounding-on-mobile\">Arredondamento de cantos no celular ou no tablet</h2>\n<p>A ferramenta funciona em telas de toque, então dá para arredondar uma foto no próprio celular que a tirou. Envie da sua galeria, arraste o controle de raio e baixe o resultado.</p>\n<p>Use o atalho Círculo completo para avatares numa tela pequena. Um toque transforma uma foto quadrada num círculo, o que é mais rápido do que arrastar o controle até o valor exato.</p>\n<p>Confira a prévia em tamanho real antes de baixar. Um raio que parece sutil na tela pequena do celular pode ficar bem mais evidente visto no computador.</p>\n<p>Os arquivos baixados vão para a sua pasta de downloads. De lá, você pode definir a imagem arredondada como foto de perfil ou compartilhar direto.</p>\n<h2 id=\"troubleshooting\">Solução de problemas comuns de arredondamento</h2>\n<p>Se os cantos mostram um fundo branco em vez de transparência, confira o formato de exportação. O JPG não tem transparência, então exporte em PNG ou WebP para manter os cantos vazados.</p>\n<p>Se a forma é uma pílula em vez de um círculo, a foto original é retangular. Corte-a em quadrado primeiro e depois aplique o atalho Círculo completo.</p>\n<p>Se os cantos parecem serrilhados, a imagem original pode ser pequena demais. Comece de uma original com resolução maior, e as curvas vão ficar suaves.</p>\n<p>Se os seus valores por canto sumiram, veja se você desligou o modo. Os valores são guardados enquanto o modo está desligado, então ligá-lo de novo os restaura.</p>\n<h2 id=\"combining-with-border\">Combinar cantos arredondados com uma borda</h2>\n<p>Arredonde os cantos primeiro e depois adicione uma borda com o <a href=\"/pt/adicionar-borda-a-imagem/\">Gerador de bordas para imagem</a>. A ferramenta de borda lê a forma da imagem, então arredondar antes mantém a moldura alinhada.</p>\n<p>Combine o raio da borda com o raio do canto. Uma borda com raio de 16 pixels ao redor de uma foto com raio de 16 pixels fica perfeita.</p>\n<p>Para um visual de cartão, use uma borda fina com um raio leve. A combinação parece um cartão de aplicativo moderno, que combina com posts de redes sociais e apresentações.</p>\n<p>Para um estilo Polaroid, mantenha os cantos quadrados. O visual clássico do filme instantâneo tem cantos vivos, e arredondá-los quebra o clima retrô.</p>\n<h2 id=\"quick-tips\">Dicas rápidas para cantos arredondados melhores</h2>\n<p>Corte na forma certa antes de arredondar. Um corte quadrado para um círculo, um corte largo para uma pílula e um corte de cartão para uma imagem de blog começam todos no cortador.</p>\n<p>Veja a prévia em tamanho real antes de baixar. Dê zoom nos cantos e confirme que as curvas estão suaves e que nada importante foi cortado.</p>\n<p>Salve o arquivo arredondado com um nome claro, como avatar-circle.png. Você pode precisar da mesma forma de novo, e um nome claro evita refazer o trabalho.</p>\n<p>Guarde a foto original sem arredondamento. Depois que os cantos são cortados numa exportação, não dá para restaurá-los a partir daquele arquivo.</p>\n<h2 id=\"rounding-for-social-post\">Arredondamento de cantos para um post de rede social</h2>\n<p>Um post com cantos arredondados parece moderno e amigável. As bordas suaves combinam com os cartões e os botões do aplicativo ao redor, então a imagem se mistura com a interface.</p>\n<p>Use um raio pequeno a médio para posts do feed. Um arredondamento leve, de 10 a 20 pixels, suaviza a imagem sem mudar o caráter dela nem esconder conteúdo.</p>\n<p>Mantenha o raio consistente em todos os seus posts. Um feed em que toda imagem tem a mesma forma de canto parece curado, enquanto raios misturados parecem aleatórios.</p>\n<p>Exporte imagens de redes sociais em JPG quando os cantos tiverem um preenchimento sólido, ou em PNG e WebP quando forem transparentes. O formato certo mantém os cantos limpos sobre qualquer fundo.</p>\n<h2 id=\"rounding-for-presentation\">Arredondamento de cantos para uma apresentação</h2>\n<p>Fotos em slides ficam melhores com cantos arredondados. As bordas suaves combinam com o design moderno do slide, e a imagem parece um elemento intencional, não um retângulo colado.</p>\n<p>Combine o raio da foto com o tema do slide. Um deck com cartões de 16 pixels precisa de fotos com raio de 16 pixels, para as imagens e os cartões se alinharem.</p>\n<p>Mantenha o raio pequeno para slides projetados em tamanho grande. Um raio enorme numa tela grande pode dominar a imagem, enquanto um arredondamento leve continua sutil em qualquer tamanho.</p>\n<p>Exporte imagens de apresentação em JPG com qualidade alta quando os cantos tiverem um preenchimento sólido. A foto precisa ficar nítida quando projetada, e uma exportação de baixa qualidade vai suavizar as curvas.</p>\n<p>Para a comparação, leia <a href=\"/pt/blog/foto-redonda-ou-cantos-arredondados/\">Foto redonda ou cantos arredondados: qual usar no avatar?</a>. Para a visão geral, veja <a href=\"/pt/blog/guia-arredondar-cantos-da-imagem/\">Como arredondar cantos de imagem: guia completo</a>, e para emoldurar uma foto arredondada, experimente o <a href=\"/pt/adicionar-borda-a-imagem/\">Gerador de bordas para imagem</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Como arredondo os cantos de uma foto no celular?","answer":"Abra a ferramenta Arredondar cantos da imagem no navegador do celular, envie a foto da sua galeria e arraste o controle de raio com o dedo. Use o atalho Círculo completo para um avatar redondo. Exporte em PNG ou WebP para manter os cantos transparentes."},{"question":"Qual é o melhor raio para uma imagem de cartão?","answer":"Um raio pequeno a médio, de 10 a 20 pixels, combina com a maioria dos cartões, dando uma suavização leve sem mudar a forma. Combine o raio da foto com o raio do cartão para um visual perfeito. Para um cartão de blog, arredonde os dois cantos de cima e deixe os dois de baixo quadrados."},{"question":"Dá para arredondar os cantos de uma imagem JPG?","answer":"Sim, mas os cantos serão preenchidos com uma cor sólida, pois o JPG não tem transparência. Escolha uma cor de preenchimento que combine com o fundo onde a imagem vai ficar, ou exporte em PNG ou WebP para manter os cantos vazados."},{"question":"Como troco a imagem sem perder meus ajustes de raio?","answer":"Carregue a imagem nova pela opção de substituir na ferramenta, que mantém seus ajustes atuais de raio e preenchimento. Depois, ajuste o raio para a foto nova e exporte com a mesma configuração."},{"question":"Por que meus cantos arredondados parecem serrilhados?","answer":"A imagem original provavelmente é pequena ou macia demais, então a curva aparece como degraus visíveis. Comece de uma original com resolução maior e as bordas vão ficar suaves. Exportar em PNG também ajuda, pois ele não tem perda de qualidade."},{"question":"Arredondar os cantos muda a largura e a altura da minha foto?","answer":"Não. Arredondar só corta as áreas dos cantos e deixa a largura e a altura iguais. O arquivo mantém as mesmas dimensões em pixels, com os cantos transparentes ou preenchidos com uma cor sólida."}];
